import {Footer} from "@/components/Footer";import {Header} from "@/components/Header";import {VehicleCard} from "@/components/VehicleCard";import {getDealer,getVehicles} from "@/lib/api";
export default async function Home(){const [dealer,vehicles]=await Promise.all([getDealer(),getVehicles()]);const featured=vehicles.filter(v=>v.is_featured).slice(0,3);return <><Header dealer={dealer}/><main id="main" style={{"--brand":dealer.primary_color,"--accent":dealer.accent_color} as React.CSSProperties}><section className="hero"><span className="eyebrow">Curated in Nigeria</span><h1>Cars with a past.<br/><em>Chosen for what’s next.</em></h1><p>{dealer.tagline}</p><div className="heroActions"><a className="button" href="/inventory">Explore inventory</a><a className="textLink" href="#story">Meet the dealer →</a></div><div className="heroArt"><span>Thoughtfully sourced<br/>Clearly described</span></div></section><section className="section"><div className="sectionHead"><div><span className="eyebrow">The selection</span><h2>Featured vehicles</h2></div><a className="textLink" href="/inventory">View all vehicles →</a></div><div className="vehicleGrid">{featured.map(v=><VehicleCard key={v.id} vehicle={v}/>)}</div></section><section className="story" id="story"><div><span className="eyebrow">Why {dealer.name}</span><h2>{dealer.story}</h2></div><div><p>{dealer.story}</p><ul><li><strong>Clear information</strong><span>Known issues and seller-provided history are shown plainly.</span></li><li><strong>Human assistance</strong><span>Speak with a real person before deciding.</span></li><li><strong>No false finish line</strong><span>An offer starts a conversation; it never silently completes a sale.</span></li></ul></div></section><section className="section"><div className="sectionHead"><div><span className="eyebrow">Just in</span><h2>New arrivals</h2></div></div><div className="vehicleGrid">{vehicles.slice(0,4).map(v=><VehicleCard key={v.id} vehicle={v}/>)}</div></section></main><Footer dealer={dealer}/></>}
