import type {Dealer} from "@/lib/types";export function Footer({dealer}:{dealer:Dealer}){return <footer id="contact"><div><strong>{dealer.name}</strong><p>{dealer.tagline}</p></div><div><span>Showroom</span><p>{dealer.address}</p><p>{dealer.opening_hours}</p></div><div><span>Talk to us</span><p><a href={`tel:${dealer.phone}`}>{dealer.phone}</a><br/><a href={`mailto:${dealer.email}`}>{dealer.email}</a></p></div><p className="fineprint">Vehicle details and condition are dealer-provided unless explicitly stated otherwise.</p></footer>}
