import Link from "next/link";import type {Vehicle} from "@/lib/types";
const money=(value:string)=>new Intl.NumberFormat("en-NG",{style:"currency",currency:"NGN",maximumFractionDigits:0}).format(Number(value));
export function VehicleCard({vehicle}:{vehicle:Vehicle}){return <article className="vehicleCard"><Link href={`/vehicles/${vehicle.slug}`}><div className="cardImage">{vehicle.images[0]?<img src={vehicle.images[0].url} alt={vehicle.images[0].alt_text}/>:<div className="placeholder">{vehicle.make[0]}</div>}<span className={`status ${vehicle.availability}`}>{vehicle.availability}</span></div><div className="cardCopy"><span>{vehicle.year} · {vehicle.transmission} · {vehicle.mileage_km.toLocaleString()} km</span><h3>{vehicle.make} {vehicle.model}</h3><strong>{money(vehicle.price)}</strong></div></Link></article>}
